/**
 * \file
 * Lookup for resources embedded by the build (res_data.c is generated by
 * app/netsurf_browser/build.py from the pinned NetSurf tree).
 */

#include <string.h>

#include "utils/errors.h"

#include "openvela/openvela.h"

struct ov_resource {
	const char *name;
	const uint8_t *data;
	size_t len;
};

extern const struct ov_resource ov_resources[];
extern const size_t ov_resource_count;

nserror ov_resource_data(const char *path, const uint8_t **data, size_t *len)
{
	for (size_t i = 0; i < ov_resource_count; i++) {
		if (strcmp(ov_resources[i].name, path) == 0) {
			*data = ov_resources[i].data;
			*len = ov_resources[i].len;
			return NSERROR_OK;
		}
	}
	return NSERROR_NOT_FOUND;
}

const uint8_t *ov_messages(size_t *len)
{
	const uint8_t *data;
	if (ov_resource_data("Messages", &data, len) != NSERROR_OK) {
		return NULL;
	}
	return data;
}
